<?php
 namespace Pterodactyl\Http\Controllers\Api\Client\Servers; use Pterodactyl\Models\Server; use Illuminate\Http\JsonResponse; use Pterodactyl\Facades\Activity; use Pterodactyl\Services\Dezerx\StartupPresets; use Pterodactyl\Http\Controllers\Api\Client\ClientApiController; use Pterodactyl\Http\Requests\Api\Client\Servers\Startup\GetStartupRequest; use Pterodactyl\Http\Requests\Api\Client\Servers\Startup\ApplyStartupPresetRequest; class StartupPresetController extends ClientApiController { public function index(GetStartupRequest $request, Server $server): JsonResponse { $server->loadMissing('egg'); $offered = array_filter( StartupPresets::forServer($server), fn (array $preset) => $preset['command'] !== $server->startup, ); return new JsonResponse([ 'presets' => array_values(array_map(fn (array $preset) => [ 'id' => $preset['id'], 'label' => $preset['label'], 'description' => $preset['description'], 'command' => $preset['command'], ], $offered)), ]); } public function update(ApplyStartupPresetRequest $request, Server $server): JsonResponse { $data = $request->validate([ 'preset' => ['required', 'string', 'max:32'], ]); $server->loadMissing('egg'); $preset = StartupPresets::find((string) $data['preset']); $offered = array_column(StartupPresets::forServer($server), 'id'); if ($preset === null || !in_array($preset['id'], $offered, true)) { return new JsonResponse([ 'errors' => [['code' => 'UnknownPreset', 'detail' => 'That is not a startup command offered for this server.']], ], 422); } $server->forceFill(['startup' => $preset['command']])->saveOrFail(); Activity::event('server:startup.preset') ->property(['preset' => $preset['label']]) ->log(); return new JsonResponse([ 'preset' => $preset['id'], 'message' => $preset['label'] . ' applied. Restart the server for it to take effect.', ]); } } 